package com.andye.warmod.radar.display;
import com.andye.warmod.block.ModBlocks; import com.andye.warmod.block.RadarDisplayPanelBlock; import java.util.*; import net.minecraft.core.BlockPos; import net.minecraft.core.Direction; import net.minecraft.world.level.LevelAccessor; import net.minecraft.world.level.block.state.BlockState;
public record RadarDisplayStructure(boolean valid,int width,int height,Direction facing,BlockPos controller,List<BlockPos> panels,int missingPanels) { public RadarDisplayStructure {panels=List.copyOf(panels);} public static RadarDisplayStructure resolve(LevelAccessor level,BlockPos start){BlockState first=level.getBlockState(start);if(!first.is(ModBlocks.RADAR_DISPLAY_PANEL))return invalid(start,Direction.NORTH,List.of(),1);Direction facing=first.getValue(RadarDisplayPanelBlock.FACING);Direction right=RadarDisplayOrientation.screenRight(facing);ArrayDeque<BlockPos> queue=new ArrayDeque<>();LinkedHashSet<BlockPos> found=new LinkedHashSet<>();queue.add(start);while(!queue.isEmpty()){BlockPos current=queue.removeFirst();if(!found.add(current))continue;if(found.size()>RadarDisplayConstants.MAX_PANELS)return invalid(start,facing,List.copyOf(found),0);for(BlockPos neighbour:List.of(current.above(),current.below(),current.relative(right),current.relative(right.getOpposite()))){BlockState state=level.getBlockState(neighbour);if(state.is(ModBlocks.RADAR_DISPLAY_PANEL)&&state.getValue(RadarDisplayPanelBlock.FACING)==facing&&!found.contains(neighbour))queue.addLast(neighbour);}}int minY=found.stream().mapToInt(BlockPos::getY).min().orElse(start.getY()),maxY=found.stream().mapToInt(BlockPos::getY).max().orElse(start.getY());int minRight=found.stream().mapToInt(p->coordinateAlong(p,right)).min().orElse(0),maxRight=found.stream().mapToInt(p->coordinateAlong(p,right)).max().orElse(0);int width=maxRight-minRight+1,height=maxY-minY+1,missing=width*height-found.size();BlockPos controller=found.stream().filter(p->p.getY()==minY&&coordinateAlong(p,right)==minRight).findFirst().orElse(start);boolean valid=width>=1&&width<=RadarDisplayConstants.MAX_WIDTH&&height>=1&&height<=RadarDisplayConstants.MAX_HEIGHT&&width*height<=RadarDisplayConstants.MAX_PANELS&&missing==0;List<BlockPos> ordered=new ArrayList<>(found);ordered.sort(Comparator.<BlockPos>comparingInt(BlockPos::getY).thenComparingInt(p->coordinateAlong(p,right)));return new RadarDisplayStructure(valid,valid?width:0,valid?height:0,facing,controller,ordered,Math.max(0,missing));} public Direction screenRight(){return RadarDisplayOrientation.screenRight(facing);} public int tileX(BlockPos position){return coordinateAlong(position,screenRight())-coordinateAlong(controller,screenRight());} public int tileY(BlockPos position){return position.getY()-controller.getY();} public BlockPos panelPosition(int tileX,int tileY){return controller.relative(screenRight(),tileX).above(tileY);} private static int coordinateAlong(BlockPos p,Direction d){return p.getX()*d.getStepX()+p.getZ()*d.getStepZ();} private static RadarDisplayStructure invalid(BlockPos p,Direction f,List<BlockPos> panels,int missing){return new RadarDisplayStructure(false,0,0,f,p,panels,missing);} }